/**
 * Mock for the native `ExpoIntentLauncher` module, which is used by the expo jest preset.
 *
 * The native module exists only on Android, so this file is written by hand instead of
 * being generated by expo-modules-test-core from the iOS implementation.
 */

export type IntentLauncherResult = {
  resultCode: number;
  data?: string;
  extra?: object;
};

export async function startActivity(
  activityAction: string,
  params: object
): Promise<IntentLauncherResult> {
  return { resultCode: -1 };
}

export function openApplication(packageName: string): void {}

export async function getApplicationIcon(packageName: string): Promise<string> {
  return '';
}
